import importlib,json,sys
results=[]
for name in ['tests.query.test_named_returning', 'tests.runtime.test_named_projection', 'tests.runtime.test_named_returning', 'tests.runtime.test_output_labels']:
 try:
  importlib.import_module(name)
  results.append({'module':name,'error':None})
 except Exception as error:
  results.append({'module':name,'error':type(error).__name__})
print(json.dumps(results))
sys.exit(1 if any(r['error'] for r in results) else 0)

